SELECT pc.id FROM potential_customer pc WHERE pc.sales_user_id = #{salesUserId} AND pc.conversion_status_code = '01' AND pc.is_active = 0
/* 오늘 생일인 고객 */ AND DATE_FORMAT(pc.birth_date, '%m-%d') = DATE_FORMAT(CURDATE(), '%m-%d')
/* 오늘 이미 웹폼 발송완료된 고객 제외 */ AND NOT EXISTS ( SELECT 1 FROM webform_issuance wi WHERE wi.customer_id = pc.id AND wi.conversion_status_code = '01' AND wi.sales_user_id = #{salesUserId} AND wi.webform_status_code = '02' AND DATE(wi.issued_at) = CURDATE() )


SELECT EXISTS (

    SELECT 1
    FROM potential_customer pc
    WHERE pc.id = #{customerId}
        AND pc.sales_user_id = #{salesUserId}
        AND pc.conversion_status_code = '01'
)

SELECT EXISTS (

    SELECT 1
    FROM integrated_customer ic
    WHERE ic.integrated_customer_id = #{customerId}
        AND ic.sales_user_id = #{salesUserId}
)

SELECT EXISTS (

    SELECT 1
    FROM potential_customer pc
    WHERE pc.id = #{customerId}
        AND pc.sales_user_id = #{salesUserId}
        AND pc.conversion_status_code = '01'
        AND pc.is_active = 0
        AND DATE_FORMAT(pc.birth_date, '%m-%d')
            = DATE_FORMAT(CURDATE(), '%m-%d')
)

SELECT EXISTS (

    SELECT 1
    FROM webform_issuance
    WHERE sales_user_id = #{salesUserId}
      AND customer_id = #{customerId}
      AND conversion_status_code = #{conversionStatusCode}
      AND webform_status_code = '02'
      AND DATE(issued_at) = CURDATE()
)

SELECT pc.id AS customerId, '01' AS conversionStatusCode FROM potential_customer pc WHERE pc.sales_user_id = #{salesUserId} AND pc.is_active = 0
UNION ALL
SELECT ic.integrated_customer_id AS customerId, '02' AS conversionStatusCode FROM integrated_customer ic WHERE ic.sales_user_id = #{salesUserId}
